begin;
select no_plan();
insert into auth.users(id) values('83000000-0000-0000-0000-000000000001'),('83000000-0000-0000-0000-000000000002');
select set_config('request.jwt.claims','{"sub":"83000000-0000-0000-0000-000000000001"}',true);
select public.bootstrap_identity();select public.create_family();select public.adopt_cat('black_short','纪念猫');
select set_config('test.home',family_id::text,true) from public.family_members where user_id=auth.uid();
select set_config('test.cat',id::text,true) from public.cats where name='纪念猫';
insert into public.cat_trips values('83100000-0000-0000-0000-000000000001',current_setting('test.home')::uuid,current_setting('test.cat')::uuid,auth.uid(),'palace',now()-interval '25 hours',now()-interval '1 hour',null);
select public.return_family_trips(current_setting('test.home')::uuid);
select set_config('test.item',id::text,true) from public.furniture_inventory where source_trip_id='83100000-0000-0000-0000-000000000001';
select is(public.furniture_state()->'inventory'->0->>'source_cat_name','纪念猫','inventory retains source');
select is(public.purchase_furniture('83200000-0000-0000-0000-000000000001','souvenir-palace',current_setting('test.home')::uuid)->>'reason','product_unavailable','souvenir not sold');
select public.room_editor('acquire','83300000-0000-0000-0000-000000000001');
select set_config('test.layout',jsonb_build_object('standard','room-standard-v1','items',jsonb_build_array(jsonb_build_object('instance_id',current_setting('test.item'),'gx',2,'gy',2,'facing','x','slot',null,'artwork','starry')))::text,true);
select is(public.save_room_layout('83200000-0000-0000-0000-000000000002','83300000-0000-0000-0000-000000000001',0,current_setting('test.layout')::jsonb)->>'status','saved','souvenir uses manual versioned save');
select is(public.save_room_layout('83200000-0000-0000-0000-000000000003','83300000-0000-0000-0000-000000000001',1,'{"standard":"room-standard-v1","items":[]}')->>'status','saved','stow saves empty layout');
select is((select count(*)::int from public.furniture_inventory where family_id=current_setting('test.home')::uuid and source='souvenir'),1,'stow keeps ownership');
select is(public.save_room_layout('83200000-0000-0000-0000-000000000004','83300000-0000-0000-0000-000000000001',2,current_setting('test.layout')::jsonb)->>'status','saved','re-place same instance');
select is((select count(*)::int from public.furniture_inventory where family_id=current_setting('test.home')::uuid and source='souvenir'),1,'re-place no duplication');
select is(public.validate_room_layout(current_setting('test.home')::uuid,jsonb_set(current_setting('test.layout')::jsonb,'{items,0,gx}','8')),'out_of_bounds','same boundary validation');
select is(public.validate_room_layout(current_setting('test.home')::uuid,jsonb_set(current_setting('test.layout')::jsonb,'{items,0,instance_id}',to_jsonb(gen_random_uuid()::text))),'inventory_missing','cannot forge souvenir instance');
insert into public.cat_trips values('83100000-0000-0000-0000-000000000002',current_setting('test.home')::uuid,current_setting('test.cat')::uuid,auth.uid(),'fuji',now()-interval '25 hours',now()-interval '1 hour',null);
select public.return_family_trips(current_setting('test.home')::uuid);
select is((select version::int from public.room_layouts where family_id=current_setting('test.home')::uuid),3,'reward does not alter layout version');
select is((select lock_token from public.room_layouts where family_id=current_setting('test.home')::uuid),'83300000-0000-0000-0000-000000000001'::uuid,'return preserves active editor lease');
select is((select count(*)::int from public.furniture_inventory where family_id=current_setting('test.home')::uuid and source='souvenir'),2,'new reward only adds inventory');
select is(public.validate_room_layout(current_setting('test.home')::uuid,jsonb_set(current_setting('test.layout')::jsonb,'{items}',(current_setting('test.layout')::jsonb->'items')||(current_setting('test.layout')::jsonb->'items'))),'duplicate_instance','duplicate same instance denied');
select * from finish();rollback;
